"""Infer lexical rules using the public CLI on small, independent examples."""
import pathlib, subprocess, json, re, shutil, sys
exe=str(pathlib.Path(sys.argv[1] if len(sys.argv)>1 else './executable').resolve())
root=pathlib.Path('/tmp/scc-rule-probes');root.mkdir(exist_ok=True)
langs=[]
for line in pathlib.Path('src/languages.txt').read_text().splitlines():
    name, exts=line.rsplit(' (',1)
    langs.append((name,exts[:-1].split(',')))
line_tokens=['//','#','--',';','%','!','REM ','rem ','Rem ',"'",'"','*','*>','**','C ','c ','dnl ','DNL ','::','\\','\\\\','.. ','NB.','-- ','#|','{-','(*','/*','<!--','<#','=begin','###','##','(*!','//!',';;','--[[']
blocks=[('/*','*/'),('/+','+/'),('(*','*)'),('{-','-}'),('<!--','-->'),('<!---','--->'),('<#','#>'),('#|','|#'),('#[',']#'),('{-','-}'),('--[[',']]'),('--[=[',']=]'),('###','###'),('=begin','=end'),('=pod','=cut'),('"""','"""'),("'''","'''"),('%{','%}'),('%{','}%'),('{','}'),('(*!','!*)'),('<%--','--%>'),('<%#','%>'),('{#','#}'),('{*','*}'),('(*','*)')]
quotes=[('"','"'),("'","'"),('`','`'),('"""','"""'),("'''","'''"),('[[',']]'),('[=[',']=]'),('@"','"'),('r"','"'),('r#"','"#'),('R"(',' )"'),('r"""','"""'),('R"""','"""'),('u"""','"""'),('f"""','"""')]
words=['if','else','elif','elseif','elsif','unless','for','foreach','while','do','switch','case','default','catch','except','try','finally','and','or','not','&&','||','?','??','?.','assert','return','break','continue','goto','func','function','def','class','when','select','match','=>','await','yield','fi','done','end','in','then','|','&','??=','raise','throw','with','where','repeat','until','loop','guard','rescue','ensure','cond','map','filter','reduce','when-let','if-let','when-not','if-not','fn','let','lambda','begin','end','IF','ELSE','ELSEIF','ELSIF','FOR','FOREACH','WHILE','DO','SWITCH','CASE','DEFAULT','CATCH','EXCEPT','TRY','FINALLY','AND','OR','NOT','WHEN','SELECT','MATCH','UNTIL','LOOP','GUARD','REPEAT','GOTO','ANDALSO','ORELSE']
cases=[]
for t in line_tokens:cases.append(('line',t,t+' x\nabc\n'))
for a,b in blocks:
    cases.append(('block',(a,b),a+' xxx\n\nxxx\n'+b+'\nabc\n'))
    cases.append(('nest',(a,b),a+' xxx\n'+a+' xxx '+b+'\nxxx\n'+b+'\nabc\n'))
for a,b in quotes: cases.append(('quote',(a,b),'x = '+a+'xxx\n\nxxx\n'+b+'\n'))
for w in words:
    for s in [' ','(', '{', ':', '\n']:
        cases.append(('complexity',w+s,' '+w+s+' xx\n'))
for i,(_,_,s) in enumerate(cases): (root/(str(i)+'.probe')).write_text(s)
rules={}
for n,(name,exts) in enumerate(langs):
    out=subprocess.check_output([exe,'-f','json','--by-file','--count-as','probe:'+name,str(root)])
    ds=json.loads(out)
    fs={int(f['Filename'].split('.')[0]):f for d in ds for f in d['Files']}
    line=[];block=[];quote=[];complexity=[]
    for i,(kind,t,s) in enumerate(cases):
        f=fs.get(i,{})
        if kind=='line' and f.get('Comment')==1 and f.get('Code')==1:line.append(t)
        if kind=='block' and f.get('Comment')==4 and f.get('Code')==1:
            nested=fs[i+1].get('Comment')==4
            if list(t) not in [b[:2] for b in block]:block.append([*t,nested])
        if kind=='quote' and f.get('Code')==4 and f.get('Blank')==0:quote.append(t)
        if kind=='complexity' and f.get('Complexity',0):complexity.append(t)
    # Remove inferred variants already covered by a shorter comment introducer.
    line=[x for x in line if not any(x!=y and x.startswith(y) for y in line)]
    # A multiline comment may have looked like a string in a language with docstrings.
    quote=[x for x in quote if x[0] not in [b[0] for b in block]]
    rules[name]={'extensions':exts,'line':line,'block':block,'quotes':quote,'complexity':complexity}
    if n%30==0: print(n,name,flush=True)
pathlib.Path('observations/inferred_rules.json').write_text(json.dumps(rules,indent=2,ensure_ascii=False)+'\n')
print('inferred',len(rules),'languages',len(cases),'cases each')
