"""Command-line parsing with interspersed arguments and short flag groups."""
import csv
import json
import os
import re
import sys
from data import HELP

BOOLS = '''binary by-file character ci cost-comparison count-ignore debug dryness gen
help include-symlinks languages locomo mcp min min-gen no-cocomo no-complexity
no-duplicates no-gen no-gitignore no-gitmodule no-hborder no-ignore no-large
no-min no-min-gen no-scc-ignore no-size percent sloccount-format trace uloc
verbose version wide'''.split()
INTS = {
    'avg-wage': 56286, 'directory-walker-job-workers': 8,
    'file-gc-count': 10000, 'file-list-queue-size': 64,
    'file-process-job-workers': 64, 'file-summary-job-queue-size': 64,
    'large-byte-count': 1000000, 'large-line-count': 40000,
    'min-gen-line-length': 255,
}
FLOATS = {'eaf': 1., 'overhead': 2.4, 'locomo-cycles': 0.,
          'locomo-input-price': 0., 'locomo-output-price': 0.,
          'locomo-review': .01, 'locomo-tps': 0.}
STRINGS = {'cocomo-project-type': 'organic', 'count-as': '',
           'currency-symbol': '$', 'format': 'tabular', 'format-multi': '',
           'locomo-config': '', 'locomo-preset': 'medium', 'output': '',
           'remap-all': '', 'remap-unknown': '', 'size-unit': 'si',
           'sort': 'files', 'sql-project': ''}
LISTS = {'exclude-dir': ['.git', '.hg', '.svn'], 'exclude-ext': [],
         'exclude-file': ['package-lock.json', 'Cargo.lock', 'yarn.lock',
                          'pubspec.lock', 'Podfile.lock', 'pnpm-lock.yaml'],
         'generated-markers': ['do not edit', '<auto-generated />'],
         'include-ext': [], 'not-match': []}
SHORT = dict(zip('mafxnhilzcdMops tuv w'.replace(' ', ''), [])) if False else {
    'm':'character', 'a':'dryness', 'x':'exclude-ext', 'n':'exclude-file',
    'f':'format', 'h':'help', 'i':'include-ext', 'l':'languages', 'z':'min-gen',
    'c':'no-complexity', 'd':'no-duplicates', 'M':'not-match', 'o':'output',
    'p':'percent', 's':'sort', 't':'trace', 'u':'uloc', 'v':'verbose', 'w':'wide',
}


class Options(dict):
    def __getattr__(self, name):
        return self.get(name.replace('_', '-'))


def usage_error(message):
    sys.stderr.write('Error: '+message+'\n'+HELP[HELP.index('Usage:'):]+ '\n')
    raise SystemExit(1)


def q(s):
    return json.dumps(s, ensure_ascii=False)


def parse(argv):
    opts = Options({k: False for k in BOOLS})
    opts.update(INTS)
    opts.update(FLOATS)
    opts.update(STRINGS)
    opts.update({k: list(v) for k,v in LISTS.items()})
    seen = set()
    paths = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        i += 1
        if arg == '--':
            paths.extend(argv[i:]); break
        if not arg.startswith('-') or arg == '-':
            paths.append(arg); continue
        parts = []
        if arg.startswith('--'):
            key, eq, val = arg[2:].partition('=')
            if key not in opts:
                usage_error('unknown flag: --'+key)
            parts.append((key, val if eq else None, '--'+key))
        else:
            remaining = arg[1:]
            while remaining:
                ch, remaining = remaining[0], remaining[1:]
                if ch not in SHORT:
                    usage_error("unknown shorthand flag: '"+ch+"' in "+arg)
                key = SHORT[ch]
                val = None
                if remaining.startswith('='):
                    val = remaining[1:]; remaining = ''
                elif key not in BOOLS and remaining:
                    val = remaining; remaining = ''
                parts.append((key, val, '-'+ch))
        for key, val, label in parts:
            if key in BOOLS:
                if val is None:
                    value = True
                elif val in ('true','TRUE','True','1','t','T'):
                    value = True
                elif val in ('false','FALSE','False','0','f','F'):
                    value = False
                else:
                    usage_error('invalid argument '+q(val)+' for '+q(label)+' flag: strconv.ParseBool: parsing '+q(val)+': invalid syntax')
            else:
                if val is None:
                    if i == len(argv):
                        usage_error('flag needs an argument: '+label)
                    val = argv[i]; i += 1
                if key in INTS:
                    try:
                        sign = -1 if val.startswith('-') else 1
                        n = val.lstrip('+-')
                        base = 16 if n.lower().startswith('0x') else 2 if n.lower().startswith('0b') else 8 if n.lower().startswith('0o') or (len(n)>1 and n.startswith('0')) else 10
                        if n.strip() != n or not n: raise ValueError()
                        value = sign*int(n,base)
                        if value < -(1<<63) or value >= (1<<63): raise OverflowError()
                    except (ValueError, OverflowError) as err:
                        message = 'value out of range' if isinstance(err,OverflowError) else 'invalid syntax'
                        usage_error('invalid argument '+q(val)+' for '+q(label)+' flag: strconv.ParseInt: parsing '+q(val)+': '+message)
                elif key in FLOATS:
                    try:
                        if val.strip()!=val: raise ValueError()
                        value = float(val)
                    except ValueError:
                        usage_error('invalid argument '+q(val)+' for '+q(label)+' flag: strconv.ParseFloat: parsing '+q(val)+': invalid syntax')
                elif key in LISTS:
                    try:
                        value = [val] if key=='not-match' else next(csv.reader([val],strict=True)) if val else []
                    except csv.Error:
                        usage_error('invalid argument '+q(val)+' for '+q(label)+' flag: parse error on line 1, column 1: bare " in non-quoted-field')
                    if key in seen: value = opts[key]+value
                else:
                    value = val
            opts[key] = value
            seen.add(key)
    opts['_seen'] = seen
    opts['_paths'] = paths or ['.']
    if opts['dryness']: opts['uloc'] = True
    if opts['wide'] or opts['format'].lower()=='wide':
        opts['wide'] = True
        opts['no-complexity'] = False
    if opts['no-min-gen']: opts['min-gen'] = True
    if opts['min-gen']: opts['min'] = opts['gen'] = True
    if opts['no-min']: opts['min'] = True
    if opts['no-gen']: opts['gen'] = True
    if opts['cost-comparison']: opts['locomo'] = True
    return opts
