    if opts.by_file:
        for f in files:
            labels='language='+json.dumps(f['Language'],ensure_ascii=False)+',file='+json.dumps(f['Location'],ensure_ascii=False)
            for name,key in keys[1:]:out.append('scc_'+name+'{'+labels+'} '+str(f[key])+'\n')
        out.append('# EOF\n')
    else:
        for row in rows:
            labels='language='+json.dumps(row['Name'],ensure_ascii=False)
            for name,key in keys:out.append('scc_'+name+'{'+labels+'} '+str(row[key])+'\n')
    return ''.join(out)


def yaml_output(rows,opts):
    tot=totals(rows)
    elapsed=.001
    if tot['Count']<=1:elapsed=0.
    def n(x):
        if not math.isfinite(x):return '.nan' if math.isnan(x) else '.inf' if x>0 else '-.inf'
        return str(int(x)) if x==int(x) else str(x)
    out=['# https://github.com/boyter/scc/','header:',
         '  url: https://github.com/boyter/scc/','  version: 3.7.0',
         '  elapsed_seconds: '+n(elapsed),'  n_files: '+str(tot['Count']),
         '  n_lines: '+str(tot['Lines']),
         '  files_per_second: '+n(safe_div(tot['Count'],elapsed)),
         '  lines_per_second: '+n(safe_div(tot['Lines'],elapsed))]
    for row in rows:
        out.append(row['Name']+':')
        out.append('  name: '+row['Name'])
        out.extend(['  code: '+str(row['Code']),'  comment: '+str(row['Comment']),'  blank: '+str(row['Blank']),'  nFiles: '+str(row['Count'])])
    out.append('SUM:')
    out.extend(['  code: '+str(tot['Code']),'  comment: '+str(tot['Comment']),'  blank: '+str(tot['Blank']),'  nFiles: '+str(tot['Count'])])
    return '\n'.join(out)+'\n'


