    return html.escape(str(x),quote=True).replace('&#x27;','&#39;').replace('&quot;','&#34;')


def html_output(rows,opts,full):
    def cells(values,tag='th'):
        return ''.join('\t\t<'+tag+'>'+hescape(v)+'</'+tag+'>\n' for v in values)
    tot=totals(rows)
    s='<table id="scc-table">\n\t<thead><tr>\n'
    s+=cells(['Language','Files','Lines','Blank','Comment','Code','Complexity','Bytes','Uloc'])
    s+='\t</tr></thead>\n\t<tbody>'
    for row in rows:
        s+='<tr>\n'+cells([row[k] for k in ['Name','Count','Lines','Blank','Comment','Code','Complexity','Bytes','ULOC']])+'\t</tr>'
        if opts.by_file:
            for f in file_sort(row['_files'],opts):
                s+='<tr>\n'+cells([f['Location'],'']+[f[k] for k in ['Lines','Blank','Comment','Code','Complexity','Bytes','Uloc']],'td')+'\t</tr>'
    s+='</tbody>\n\t<tfoot><tr>\n'+cells(['Total']+[tot[k] for k in ['Count','Lines','Blank','Comment','Code','Complexity','Bytes','ULOC']])+'\t</tr>'
    if not opts.no_cocomo:
        s+='\n\t<tr>\n\t\t<th colspan="9">'+'<br>'.join(hescape(x) for x in cocomo_text(tot['Code'],opts))+'<br></th>\n\t</tr></tfoot>\n\t</table>'
