SQL_SCHEMA='''create table metadata (   -- github.com/boyter/scc v 3.7.0
             timestamp text,
             Project   text,
             elapsed_s real,
             estimated_cost real,
             estimated_schedule_months real,
             estimated_people real);
create table t        (
             Project       text   ,
             Language      text   ,
             File          text   ,
             File_dirname  text   ,
             File_basename text   ,
             nByte         integer,
             nBlank        integer,
             nComment      integer,
             nCode         integer,
             nComplexity   integer,
             nUloc         integer    
);'''


def sql_output(rows,files,opts,schema):
    def q(s):return "'"+s.replace("'","''")+"'"
    project=opts.sql_project or ','.join(opts['_paths'])
    out=[SQL_SCHEMA if schema else '', 'begin transaction;']
    for f in files:
        directory=os.path.dirname(f['Location'])
        directory=directory+'/' if directory else ''
        values=[q(s) for s in [project,f['Language'],f['Location'],directory,f['Filename']]]
        values.extend(str(f[k]) for k in ['Bytes','Blank','Comment','Code','Complexity','Uloc'])
        out.append('insert into t values('+', '.join(values)+');')
    tot=totals(rows);cost=cocomo(tot['Code'],opts)
    timestamp=datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    out.extend(['commit;','begin transaction;',
                'insert into metadata values('+q(timestamp)+', '+q(project)+', 0.001000, '+fnum(cost['cost'],6)+', '+fnum(cost['schedule'],6)+', '+fnum(cost['people'],6)+');','commit;'])
    return '\n'.join(out)


def format_report(rows,files,opts,kind=None):
    kind=(kind or opts.format).lower()
    if kind in ('json','json2'):
        s=public_summary(rows)
        if kind=='json2':
            t=totals(rows); c=cocomo(t['Code'],opts)
            s={'languageSummary':s,'estimatedCost':c['cost'],'estimatedScheduleMonths':c['schedule'],'estimatedPeople':c['people']}
            if opts.locomo:s.update(locomo(t['Code'],t['Complexity'],opts))
        try:return go_json(s)
        except ValueError:return ''
    if kind in ('csv','csv-stream'):return csv_output(rows,files,opts,kind=='csv-stream')
    if kind=='openmetrics':return openmetrics(rows,files,opts)
    if kind=='cloc-yaml':return yaml_output(rows,opts)
    if kind in ('html','html-table'):return html_output(rows,opts,kind=='html')
    if kind in ('sql','sql-insert'):return sql_output(rows,files,opts,kind=='sql')
    if kind=='wide':
        from options import Options
        opts=Options(opts);opts['wide']=True;opts['no-complexity']=False
    return table(rows,opts)
