        out.append('  name: '+row['Name'])
        out.extend(['  code: '+str(row['Code']),'  comment: '+str(row['Comment']),'  blank: '+str(row['Blank']),'  nFiles: '+str(row['Count'])])
    out.append('SUM:')
    out.extend(['  code: '+str(tot['Code']),'  comment: '+str(tot['Comment']),'  blank: '+str(tot['Blank']),'  nFiles: '+str(tot['Count'])])
    return '\n'.join(out)+'\n'


def hescape(x):
    return html.escape(str(x),quote=True).replace('&#x27;','&#39;').replace('&quot;','&#34;')


def html_output(rows,opts,full):
    def cells(values,tag='th'):
        return ''.join('\t\t<'+tag+'>'+hescape(v)+'</'+tag+'>\n' for v in values)
    tot=totals(rows)
    s='<table id="scc-table">\n\t<thead><tr>\n'
    s+=cells(['Language','Files','Lines','Blank','Comment','Code','Complexity','Bytes','Uloc'])
    s+='\t</tr></thead>\n\t<tbody>'
    for row in rows:
        s+='<tr>\n'+cells([row[k] for k in ['Name','Count','Lines','Blank','Comment','Code','Complexity','Bytes','ULOC']])+'\t</tr>'
        if opts.by_file:
            for f in file_sort(row['_files'],opts):
                s+='<tr>\n'+cells([f['Location'],'']+[f[k] for k in ['Lines','Blank','Comment','Code','Complexity','Bytes','Uloc']],'td')+'\t</tr>'
    s+='</tbody>\n\t<tfoot><tr>\n'+cells(['Total']+[tot[k] for k in ['Count','Lines','Blank','Comment','Code','Complexity','Bytes','ULOC']])+'\t</tr>'
    if not opts.no_cocomo:
        s+='\n\t<tr>\n\t\t<th colspan="9">'+'<br>'.join(hescape(x) for x in cocomo_text(tot['Code'],opts))+'<br></th>\n\t</tr></tfoot>\n\t</table>'
    else:s+='</tfoot></table>'
    if full:
        s='<html lang="en"><head><meta charset="utf-8" /><title>scc html output</title><style>table { border-collapse: collapse; }td, th { border: 1px solid #999; padding: 0.5rem; text-align: left;}</style></head><body>'+s+'</body></html>'
    return s+'\n'


SQL_SCHEMA='''create table metadata (   -- github.com/boyter/scc v 3.7.0
             timestamp text,
             Project   text,
             elapsed_s real,
             estimated_cost real,
             estimated_schedule_months real,
             estimated_people real);
create table t        (
             Project       text   ,
             Language      text   ,
             File          text   ,
             File_dirname  text   ,
             File_basename text   ,
             nByte         integer,
             nBlank        integer,
             nComment      integer,
             nCode         integer,
             nComplexity   integer,
             nUloc         integer    
);'''


def sql_output(rows,files,opts,schema):
    def q(s):return "'"+s.replace("'","''")+"'"
    project=opts.sql_project or ','.join(opts['_paths'])
    out=[SQL_SCHEMA if schema else '', 'begin transaction;']
    for f in files:
        directory=os.path.dirname(f['Location'])
        directory=directory+'/' if directory else ''
        values=[q(s) for s in [project,f['Language'],f['Location'],directory,f['Filename']]]
        values.extend(str(f[k]) for k in ['Bytes','Blank','Comment','Code','Complexity','Uloc'])
        out.append('insert into t values('+', '.join(values)+');')
    tot=totals(rows);cost=cocomo(tot['Code'],opts)
    timestamp=datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    out.extend(['commit;','begin transaction;',
                'insert into metadata values('+q(timestamp)+', '+q(project)+', 0.001000, '+fnum(cost['cost'],6)+', '+fnum(cost['schedule'],6)+', '+fnum(cost['people'],6)+');','commit;'])
    return '\n'.join(out)


def format_report(rows,files,opts,kind=None):
    kind=(kind or opts.format).lower()
    if kind in ('json','json2'):
        s=public_summary(rows)
        if kind=='json2':
            t=totals(rows); c=cocomo(t['Code'],opts)
            s={'languageSummary':s,'estimatedCost':c['cost'],'estimatedScheduleMonths':c['schedule'],'estimatedPeople':c['people']}
            if opts.locomo:s.update(locomo(t['Code'],t['Complexity'],opts))
        try:return go_json(s)
        except ValueError:return ''
    if kind in ('csv','csv-stream'):return csv_output(rows,files,opts,kind=='csv-stream')
    if kind=='openmetrics':return openmetrics(rows,files,opts)
    if kind=='cloc-yaml':return yaml_output(rows,opts)
    if kind in ('html','html-table'):return html_output(rows,opts,kind=='html')
    if kind in ('sql','sql-insert'):return sql_output(rows,files,opts,kind=='sql')
    if kind=='wide':
        from options import Options
        opts=Options(opts);opts['wide']=True;opts['no-complexity']=False
    return table(rows,opts)
