        if isinstance(args.get(key),str):argv.extend(['--'+key.replace('_','-'),args[key]])
    opts=parse(argv)
    if opts.sort in ('blank','comment'):opts['sort']+='s'
    files=Counter(opts).run([path]);rows=summary(files,opts);t=totals(rows)
    metrics=[('files','Count'),('lines','Lines'),('code','Code'),('comment','Comment'),('blank','Blank'),('complexity','Complexity'),('bytes','Bytes')]
    languages=[]
    for row in rows:
        lang={'name':row['Name']}
        lang.update({a:row[b] for a,b in metrics})
        if opts.by_file:
            fs=file_sort(row['_files'],opts,'name')
            limit=args.get('limit',10)
            if not isinstance(limit,(float,int)):limit=10
            if limit>=0:fs=fs[:int(limit)]
            lang['fileList']=[dict(location=f['Location'],filename=f['Filename'],language=f['Language'],
                                  **{a:f[b] for a,b in metrics if a!='files'}) for f in fs]
        languages.append(lang)
    c=cocomo(t['Code'],opts)
    report={'path':path,'languages':languages,'totals':{a:t[b] for a,b in metrics},
            'cocomo':dict(estimatedCost=c['cost'],estimatedScheduleMonths=c['schedule'],estimatedPeople=c['people'])}
    if opts.locomo:
        l=locomo(t['Code'],t['Complexity'],opts)
        report['locomo']={k[12].lower()+k[13:]:v for k,v in l.items()}
    report.update(totalFiles=t['Count'],totalLines=t['Lines'],totalCode=t['Code'])
    # Round-trip through the compact writer to use the same integral-float and
    # escaping conventions, then pretty print the textual tool response.
    cleaned=json.loads(go_json(report))
    return text_result(json.dumps(cleaned,indent=2,ensure_ascii=False).replace('&','\\u0026').replace('<','\\u003c').replace('>','\\u003e'))


def serve():
    for line in sys.stdin:
        try:req=json.loads(line)
        except (ValueError,TypeError):
            response={'jsonrpc':'2.0','id':None,'error':{'code':-32700,'message':'Parse error'}}
            print(go_json(response),flush=True);continue
        if not isinstance(req,dict):continue
        ident=req.get('id')
        if 'id' not in req:continue
        method=req.get('method');params=req.get('params') or {}
        response={'jsonrpc':'2.0','id':ident}
        if method=='initialize':
            version=params.get('protocolVersion','2024-11-05')
            if version not in ('2024-11-05','2025-03-26','2025-06-18'):version='2025-03-26'
            response['result']={'protocolVersion':version,'capabilities':{'tools':{}},'serverInfo':{'name':'scc','version':'3.7.0'}}
        elif method=='ping':response['result']={}
        elif method=='tools/list':response['result']=TOOLS
        elif method=='tools/call':
            name=params.get('name','')
            if name=='analyze':response['result']=analyze(params.get('arguments') or {})
            else:response['error']={'code':-32602,'message':"tool '"+name+"' not found: tool not found"}
        else:response['error']={'code':-32601,'message':'Method not found'}
        print(go_json(response),flush=True)
